import { useState } from 'react';
import {
  JxPage,
  JxHeader,
  JxBadge,
  JxSection,
  JxDivider,
  JxSegmentedControl,
  JxSegmentedItem,
  JxSlider,
  JxSwitch,
  JxSelect,
  JxSelectOption,
  JxLabel,
  JxStack,
} from '@jinx-ui/react';

type Theme = 'light' | 'dark' | 'system';
type FontFamily = 'system' | 'serif' | 'mono';

export interface AppearanceSettingsValue {
  theme: Theme;
  scale: number;
  compact: boolean;
  font: FontFamily;
}

interface AppearanceSettingsProps {
  onChange?: (value: AppearanceSettingsValue) => void;
}

const themeLabels: Record<Theme, string> = {
  light: 'Светлая',
  dark: 'Тёмная',
  system: 'Системная',
};

function AppearanceSettings({ onChange }: AppearanceSettingsProps) {
  const [theme, setTheme] = useState<Theme>('system');
  const [scale, setScale] = useState<number>(100);
  const [compact, setCompact] = useState<boolean>(false);
  const [font, setFont] = useState<FontFamily>('system');

  const emit = (next: Partial<AppearanceSettingsValue>) => {
    onChange?.({
      theme,
      scale,
      compact,
      font,
      ...next,
    });
  };

  const handleThemeChange = (value: Theme) => {
    setTheme(value);
    emit({ theme: value });
  };

  const handleScaleChange = (value: number) => {
    setScale(value);
    emit({ scale: value });
  };

  const handleCompactChange = (value: boolean) => {
    setCompact(value);
    emit({ compact: value });
  };

  const handleFontChange = (value: FontFamily) => {
    setFont(value);
    emit({ font: value });
  };

  return (
    <JxPage>
      <JxHeader
        title="Внешний вид"
        actions={<JxBadge tone="neutral">{themeLabels[theme]}</JxBadge>}
      />

      <JxSection title="Тема">
        <JxSegmentedControl
          value={theme}
          onValueChange={(value) => handleThemeChange(value as Theme)}
        >
          <JxSegmentedItem value="light">Светлая</JxSegmentedItem>
          <JxSegmentedItem value="dark">Тёмная</JxSegmentedItem>
          <JxSegmentedItem value="system">Системная</JxSegmentedItem>
        </JxSegmentedControl>
      </JxSection>

      <JxSection title="Масштаб интерфейса">
        <JxStack direction="row" align="center" gap="md">
          <JxSlider
            min={80}
            max={140}
            step={5}
            value={scale}
            onValueChange={handleScaleChange}
            style={{ flex: 1 }}
          />
          <JxLabel style={{ color: 'var(--jx-color-text-secondary)', minWidth: '3.5em', textAlign: 'right' }}>
            {scale}%
          </JxLabel>
        </JxStack>
      </JxSection>

      <JxSection title="Плотная вёрстка">
        <JxStack direction="row" align="center" justify="space-between">
          <JxLabel>Уменьшить отступы элементов</JxLabel>
          <JxSwitch checked={compact} onCheckedChange={handleCompactChange} />
        </JxStack>
      </JxSection>

      <JxDivider />

      <JxSection title="Ещё">
        <JxStack direction="row" align="center" justify="space-between">
          <JxLabel>Шрифт</JxLabel>
          <JxSelect
            value={font}
            onValueChange={(value) => handleFontChange(value as FontFamily)}
          >
            <JxSelectOption value="system">Системный</JxSelectOption>
            <JxSelectOption value="serif">С засечками</JxSelectOption>
            <JxSelectOption value="mono">Моноширинный</JxSelectOption>
          </JxSelect>
        </JxStack>
      </JxSection>
    </JxPage>
  );
}

export default AppearanceSettings;

